// Saved records: store keys, the merge of a sighting, counts, shape, retention.

import type { SandboxTunerApplied, SandboxTunerCounts, SandboxTunerLatest, SandboxTunerRecord } from '../types'
import { isGuardedPath, normalHost } from './names'
import { isCount, isListOf, isPlainObject, isText } from './shapes'
import type { Sighting } from './sightings'

// Writers keep independent records.
export const WRITER_PREFIX = 'writer:'
export const HIDDEN_PREFIX = 'hidden:'
export const JOURNAL_PREFIX = 'applied:'
const JOURNAL_LIMIT = 50

const RECORD_LIMIT = 300
const RECORD_AGE_MS = 30 * 24 * 60 * 60 * 1000
const PORT_LIMIT = 5
const PROGRAM_LIMIT = 3
const SESSION_LIMIT = 20
const COUNTERS = ['blocked', 'refused', 'listed', 'inferred'] as const
const KINDS: ReadonlySet<unknown> = new Set(['host', 'path'])

export function recordKey(sighting: Pick<Sighting, 'kind' | 'target'>): string {
  return `${sighting.kind}:${sighting.target}`
}

function joinNewest<T>(list: readonly T[], item: T, limit: number): T[] {
  return [...list.filter(value => value !== item), item].slice(-limit)
}

/** Distinct values, the newer record's last so that the cut keeps them: a value in both takes its newer place. */
function mergeNewest<T>(older: readonly T[], newer: readonly T[], limit: number): T[] {
  const joined = [...older, ...newer]
  return joined.filter((value, index) => joined.lastIndexOf(value) === index).slice(-limit)
}

export function mergeSighting(record: SandboxTunerRecord | undefined, sighting: Sighting, sessionId: string | null, now: number): SandboxTunerRecord {
  const base: SandboxTunerRecord = record ?? {
    key: recordKey(sighting),
    kind: sighting.kind,
    target: sighting.target,
    counts: { blocked: 0, refused: 0, listed: 0, inferred: 0 },
    ports: [],
    sample: '',
    seenWith: [],
    sessions: [],
    firstSeen: now,
    lastSeen: now,
    isHidden: false,
  }
  return {
    ...base,
    counts: {
      ...base.counts,
      [sighting.counter]: base.counts[sighting.counter] + 1,
      refused: base.counts.refused + (sighting.reason === 'refused' ? 1 : 0),
    },
    ports: sighting.ports.reduce((list, port) => joinNewest(list, port, PORT_LIMIT), base.ports),
    seenWith: sighting.program === '' ? base.seenWith : joinNewest(base.seenWith, sighting.program, PROGRAM_LIMIT),
    sessions: sessionId === null ? base.sessions : joinNewest(base.sessions, sessionId, SESSION_LIMIT),
    // A folder keeps a protected or key file as its sample, so a later write beside it cannot bring Allow back.
    sample: base.kind === 'path' && isGuardedPath(base.sample) && !isGuardedPath(sighting.detail) ? base.sample : sighting.detail,
    lastSeen: now,
  }
}

export function sightingTotal(counts: SandboxTunerCounts): number {
  return counts.blocked + counts.listed + counts.inferred
}

export function allowCount(counts: SandboxTunerCounts): number {
  return sightingTotal(counts) - counts.refused
}

export function isRecord(value: unknown): value is SandboxTunerRecord {
  if (!isPlainObject(value) || !isPlainObject(value.counts)) return false
  const counts = value.counts
  return (
    KINDS.has(value.kind) &&
    isText(value.target) &&
    value.key === `${String(value.kind)}:${value.target}` &&
    COUNTERS.every(name => isCount(counts[name])) &&
    isListOf(value.ports, isCount) &&
    isText(value.sample) &&
    isListOf(value.seenWith, isText) &&
    isListOf(value.sessions, isText) &&
    isCount(value.firstSeen) &&
    isCount(value.lastSeen) &&
    typeof value.isHidden === 'boolean'
  )
}

/** The record keys omitted from the display after 30 days or beyond the 300 newest targets. */
export function staleKeys(records: readonly SandboxTunerRecord[], now: number): string[] {
  const fresh = records.filter(record => now - record.lastSeen <= RECORD_AGE_MS)
  const kept = new Set([...fresh].sort((a, b) => b.lastSeen - a.lastSeen).slice(0, RECORD_LIMIT).map(record => record.key))
  return records.filter(record => !kept.has(record.key)).map(record => record.key)
}

/** The records that the display shows at `now`: each seen within 30 days, at most the 300 newest. */
export function shownRecords(records: readonly SandboxTunerRecord[], now: number): SandboxTunerRecord[] {
  const stale = new Set(staleKeys(records, now))
  return records.filter(record => !stale.has(record.key))
}

/** The 50 newest history entries plus every unresolved edit, oldest first. */
export function journalOf(entries: readonly SandboxTunerApplied[]): SandboxTunerApplied[] {
  const sorted = [...entries].sort((a, b) => a.appliedAt - b.appliedAt || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
  const unresolved = (entry: SandboxTunerApplied) => entry.applyState === 'pending' || isUndoUnresolved(entry)
  const history = sorted.filter(entry => !unresolved(entry)).slice(-JOURNAL_LIMIT)
  return sorted.filter(entry => unresolved(entry) || history.includes(entry))
}

/** An unconfirmed removal retains its retry action. */
export function isUndoUnresolved(entry: SandboxTunerApplied): boolean {
  return entry.undoState === 'pending' || entry.undoState === 'retry'
}

export function hasLaterOwner(journal: readonly SandboxTunerApplied[], entry: SandboxTunerApplied): boolean {
  return journal.some(item => item.id !== entry.id && item.file === entry.file && item.settingsKey === entry.settingsKey &&
    (entry.settingsKey === 'sandbox.filesystem.allowWrite' ? item.entry === entry.entry : normalHost(item.entry) === normalHost(entry.entry)) &&
    item.appliedAt >= entry.appliedAt)
}

export function isPressedAgain(journal: readonly SandboxTunerApplied[], written: SandboxTunerApplied): boolean {
  return hasLaterOwner(journal, written) || journal.some(item => item.id === written.id && item.undoneAt !== written.undoneAt)
}

/** True when a press changed settings for the target of the latest block at or after that block. */
export function isFixedSince(journal: readonly SandboxTunerApplied[], latest: SandboxTunerLatest): boolean {
  return journal.some(entry => entry.applyState !== 'pending' && entry.recordKey === latest.recordKey && entry.appliedAt >= latest.at)
}

/** Combine independent writers without losing a protected sample or inferred evidence. */
export function aggregateRecords(records: readonly SandboxTunerRecord[]): SandboxTunerRecord[] {
  const result = new Map<string, SandboxTunerRecord>()
  for (const record of [...records].sort((a, b) => a.lastSeen - b.lastSeen)) {
    const previous = result.get(record.key)
    if (previous === undefined) { result.set(record.key, record); continue }
    result.set(record.key, {
      ...record,
      counts: {
        blocked: previous.counts.blocked + record.counts.blocked,
        refused: previous.counts.refused + record.counts.refused,
        listed: previous.counts.listed + record.counts.listed,
        inferred: previous.counts.inferred + record.counts.inferred,
      },
      sample: isGuardedPath(previous.sample) ? previous.sample : record.sample,
      ports: mergeNewest(previous.ports, record.ports, PORT_LIMIT),
      seenWith: mergeNewest(previous.seenWith, record.seenWith, PROGRAM_LIMIT),
      sessions: mergeNewest(previous.sessions, record.sessions, SESSION_LIMIT),
      firstSeen: Math.min(previous.firstSeen, record.firstSeen),
    })
  }
  return [...result.values()]
}

files.hooks/settings-file.ts:
// Parses, edits, and serializes the user settings file, formats and parses the record of its lock file, and checks the
// shape of a journal entry.

import type { SandboxTunerApplied, SandboxTunerSettingsKey } from '../types'
import { causeOf } from './diagnostics'
import { displayPath, normalHost, plainText } from './names'
import { isCount, isListOf, isPlainObject, isText } from './shapes'

export type FileInfo = { path: string; display: string; backup: string; backupDisplay: string; lock: string; lockDisplay: string }
export type ParsedSettings = { value: Record<string, unknown>; bom: string; trailingNewline: boolean; isCanonical: boolean }
export type Refusal =
  | { refusal: 'invalid-json'; message: string }
  | { refusal: 'wrong-type'; path: string; found: string; expected: string }
type AddResult = { value: Record<string, unknown>; created: string[] } | { isPresent: true } | Refusal
type RemoveResult = { value: Record<string, unknown> } | { isAbsent: true } | Refusal
type KeyPath = { parents: readonly string[]; leaf: string }
type Link = { holder: Record<string, unknown>; name: string; dotted: string }
type Walked = { node: Record<string, unknown>; links: Link[]; created: string[] }

const BOM = '\ufeff'
const KEY_PATHS: Readonly<Record<SandboxTunerSettingsKey, KeyPath>> = {
  'sandbox.network.allowedDomains': { parents: ['sandbox', 'network'], leaf: 'allowedDomains' },
  'sandbox.network.deniedDomains': { parents: ['sandbox', 'network'], leaf: 'deniedDomains' },
  'sandbox.filesystem.allowWrite': { parents: ['sandbox', 'filesystem'], leaf: 'allowWrite' },
}
const HOST_KEYS: ReadonlySet<SandboxTunerSettingsKey> = new Set(['sandbox.network.allowedDomains', 'sandbox.network.deniedDomains'])

/**
 * The paths of a settings file, its backup, and its lock file, each with the text that shows it: CLAUDE_CONFIG_DIR can
 * hold any character.
 */
export function fileInfo(path: string, home: string | undefined): FileInfo {
  const backup = `${path.slice(0, path.lastIndexOf('/'))}/backups/settings.json.sandbox-tuner.bak`
  const lock = `${path}.sandbox-tuner.lock`
  return { path, display: plainText(displayPath(path, home)), backup, backupDisplay: plainText(displayPath(backup, home)), lock, lockDisplay: plainText(displayPath(lock, home)) }
}

/** Who holds the lock of a settings file: the token of one press, and when it took the lock. */
export type LockRecord = { holder: string; since: number }

/** The text of a lock file: held by the press `holder` since `since`, or free since `since` when `holder` is null. */
export function lockText(holder: string | null, since: number): string {
  return `${JSON.stringify({ holder, since })}\n`
}

/**
 * What a lock file holds: its holder, `free` when the file is missing or free, or null when its text is no lock record,
 * such as an empty file that a write has not finished.
 */
export function readLock(text: string | null): LockRecord | 'free' | null {
  if (text === null) return 'free'
  let value: unknown
  try {
    value = JSON.parse(text)
  } catch {
    return null
  }
  if (!isPlainObject(value) || !isCount(value.since)) return null
  if (value.holder === null) return 'free'
  return isText(value.holder) && value.holder !== '' ? { holder: value.holder, since: value.since } : null
}

function typeName(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return 'an array'
  return typeof value === 'object' ? 'an object' : `a ${typeof value}`
}

function wrongType(path: string, value: unknown, expected: string): Refusal {
  return { refusal: 'wrong-type', path, found: typeName(value), expected }
}

/**
 * The JSON parser's reason without the text of the file, because settings can hold secrets in `env` and the
 * reason goes to the debug log. The parsers quote the file near the fault: V8 quotes the token and an excerpt,
 * JavaScriptCore quotes the identifier. So all from the first quote to the last one becomes `…`. JavaScriptCore
 * also names a bad escape character without quotes, so that character goes too.
 */
export function parserReason(message: string): string {
  return message
    .replace(/["'][\s\S]*["'](?:\.\.\.)?/, '…')
    .replace(/(escape character) \S+/, '$1')
    .replace(/\s+/g, ' ')
    .trim()
}

export function parseSettings(text: string): ParsedSettings | Refusal {
  const bom = text.startsWith(BOM) ? BOM : ''
  const body = text.slice(bom.length)
  const isBlank = body.trim() === ''
  let value: unknown
  try {
    value = isBlank ? {} : JSON.parse(body)
  } catch (error) {
    return { refusal: 'invalid-json', message: parserReason(causeOf(error)) }
  }
  if (!isPlainObject(value)) return wrongType('the top level', value, 'an object')
  const canonical = JSON.stringify(value, null, 2)
  return { value, bom, trailingNewline: isBlank || body.endsWith('\n'), isCanonical: body === canonical || body === `${canonical}\n` }
}

function cloneSettings(root: Record<string, unknown>): Record<string, unknown> {
  return JSON.parse(JSON.stringify(root)) as Record<string, unknown>
}

function walk(root: Record<string, unknown>, parents: readonly string[], isCreating: true): Walked | Refusal
function walk(root: Record<string, unknown>, parents: readonly string[], isCreating: false): Walked | Refusal | 'missing'
function walk(root: Record<string, unknown>, parents: readonly string[], isCreating: boolean): Walked | Refusal | 'missing' {
  const walked: Walked = { node: root, links: [], created: [] }
  for (const name of parents) {
    const dotted = [...walked.links.map(link => link.name), name].join('.')
    const child = walked.node[name]
    if (child === undefined && !isCreating) return 'missing'
    if (child !== undefined && !isPlainObject(child)) return wrongType(dotted, child, 'an object')
    if (child === undefined) {
      walked.node[name] = {}
      walked.created.push(dotted)
    }
    walked.links.push({ holder: walked.node, name, dotted })
    walked.node = walked.node[name] as Record<string, unknown>
  }
  return walked
}

function listAt(node: Record<string, unknown>, leaf: string, key: SandboxTunerSettingsKey): string[] | undefined | Refusal {
  const list = node[leaf]
  return list === undefined || isListOf(list, isText) ? list : wrongType(key, list, 'an array of strings')
}

function sameEntry(key: SandboxTunerSettingsKey, left: string, right: string): boolean {
  return HOST_KEYS.has(key) ? normalHost(left) === normalHost(right) : left === right
}

export function addEntry(root: Record<string, unknown>, key: SandboxTunerSettingsKey, entry: string): AddResult {
  const copy = cloneSettings(root)
  const { parents, leaf } = KEY_PATHS[key]
  const walked = walk(copy, parents, true)
  if ('refusal' in walked) return walked
  const list = listAt(walked.node, leaf, key)
  if (list === undefined) {
    walked.node[leaf] = [entry]
    return { value: copy, created: [...walked.created, key] }
  }
  if ('refusal' in list) return list
  if (list.some(item => sameEntry(key, item, entry))) return { isPresent: true }
  list.push(entry)
  return { value: copy, created: walked.created }
}

export function removeEntry(root: Record<string, unknown>, key: SandboxTunerSettingsKey, entry: string, created: readonly string[]): RemoveResult {
  const copy = cloneSettings(root)
  const { parents, leaf } = KEY_PATHS[key]
  const walked = walk(copy, parents, false)
  if (walked === 'missing') return { isAbsent: true }
  if ('refusal' in walked) return walked
  const list = listAt(walked.node, leaf, key)
  if (list === undefined) return { isAbsent: true }
  if ('refusal' in list) return list
  const index = list.findIndex(item => sameEntry(key, item, entry))
  if (index === -1) return { isAbsent: true }
  list.splice(index, 1)
  for (const link of [...walked.links, { holder: walked.node, name: leaf, dotted: key }].reverse()) {
    const value = link.holder[link.name]
    const isEmpty = (Array.isArray(value) && value.length === 0) || (isPlainObject(value) && Object.keys(value).length === 0)
    if (isEmpty && created.includes(link.dotted)) delete link.holder[link.name]
  }
  return { value: copy }
}

export function serializeSettings(value: Record<string, unknown>, format: Pick<ParsedSettings, 'bom' | 'trailingNewline'>): string {
  return `${format.bom}${JSON.stringify(value, null, 2)}${format.trailingNewline ? '\n' : ''}`
}

/** The shape of one journal entry. */
export function isApplied(value: unknown): value is SandboxTunerApplied {
  return (
    isPlainObject(value) &&
    isText(value.id) &&
    isText(value.recordKey) &&
    (value.action === 'allow' || value.action === 'deny') &&
    isText(value.settingsKey) &&
    Object.hasOwn(KEY_PATHS, value.settingsKey) &&
    isText(value.entry) &&
    isText(value.file) &&
    (value.backup === null || isText(value.backup)) &&
    isListOf(value.created, isText) &&
    isCount(value.appliedAt) &&
    (value.undoneAt === null || isCount(value.undoneAt)) &&
    (value.applyState === undefined || (value.applyState === 'pending' && value.undoneAt === null)) &&
    (value.undoState === undefined || (value.undoneAt !== null && ['pending', 'retry', 'superseded'].includes(String(value.undoState))))
  )
}

files.hooks/sightings.ts:
// Reads one Bash call into sightings.

import type { SandboxTunerKind, SandboxTunerLatest } from '../types'
import { absolutePath, folderTarget, isGuardedPath, plainText, programName, splitHost } from './names'
import { recordKey } from './records'

type Counter = 'blocked' | 'listed' | 'inferred'
type BlockReason = SandboxTunerLatest['reason']
export type Sighting = {
  kind: SandboxTunerKind
  target: string
  counter: Counter
  reason: BlockReason | null
  reasonText: string
  ports: readonly number[]
  detail: string
  program: string
}
type Gate = 'sandbox-on' | 'sandbox-required'
export type GatedSighting = { gate: Gate; sighting: Sighting }
type CallSightings = { reports: Sighting[]; gated: GatedSighting[]; unknownLine: string | null; observation?: { operation: string; detail: string }; skipped?: true }
export type SandboxFacts = { isEnabled: boolean; allowsUnsandboxed: boolean }
export type BashCall = { command: string; isBackground: boolean; isUnsandboxed: boolean; allowedDomains: readonly string[] }
export type BashOutcome = { backgroundTaskId?: string; isDenied: boolean; isError: boolean; isReadOnly?: boolean; isUnsandboxed?: boolean; text: string; stderr: string }

const SCAN_LIMIT = 200_000
// No host, path, or reason that the sandbox reports is longer than the longest path a file system takes, or holds a
// character that the engine refuses to draw. Such a one is noise, such as output that imitates a report.
const SIGHTING_TEXT_LIMIT = 4096
const PATH_LIMIT = 3
const UNKNOWN_LIMIT = 80
const OPEN_TAG = '<sandbox_violations>'
const CLOSE_TAG = '</sandbox_violations>'
// Claude Code 2.1.296 ends the text of a failed call with its report, each tag on a line of its own. Only its proxy
// note can follow the report.
const REPORT_OPEN = `\n${OPEN_TAG}\n`
const REPORT_CLOSE = `\n${CLOSE_TAG}`
const PROXY_NOTE = '\n\n[agent-proxy] While this command ran, '
const NETWORK = /^deny network-outbound (\S+) \((.*)\)$/
const MAC_LINE = /^\S+\(\d+\) deny\(\d+\) \S/
const MAC_FILE = /^\S+\(\d+\) deny\(\d+\) file-/
const MAC_WRITE = /^\S+\(\d+\) deny\(\d+\) file-write-[a-z-]+\s+(\/.*)$/
const LINUX_WRITE = /^deny [a-z0-9_]+ (\/.*)$/
// The start of every report line: `deny ` for a network line and on Linux, `<program>(<pid>) ` on macOS.
const REPORT_START = /^(?:deny |\S+\(\d+\) )/
const EXIT_CODE = /^Exit code \d+/
const PERMISSION_ERROR = /operation not permitted|read-only file system/i
const SOCKET_WORDS = /\b(?:listen|connect|socket)\b/i
const PATH_START = /(?:^|[\s'"‘`(])\/(?!\/)/g
const PATH_CANDIDATE = /(?:^|[\s'"‘`(])(\/(?!\/)[^\s'"’`:,)]+)(?=[:'"’`,)]|$)/g
const DEVICE_PATH = /^\/(?:dev|proc|sys)\//

function fits(sighting: Sighting): boolean {
  const text = `${sighting.detail}${sighting.reasonText}`
  return text.length <= SIGHTING_TEXT_LIMIT && plainText(text) === text
}

function distinct<T>(items: readonly T[], keyOf: (item: T) => string): T[] {
  const seen = new Set<string>()
  return items.filter(item => {
    const key = keyOf(item)
    const isNew = !seen.has(key)
    seen.add(key)
    return isNew
  })
}

/** A line that must speak for its target: a refusal keeps Deny, and a protected or key file keeps Allow away. */
function isWeighty(sighting: Sighting): boolean {
  return sighting.reason === 'refused' || (sighting.kind === 'path' && isGuardedPath(sighting.detail))
}

/**
 * One sighting per target and counter, however many lines of the call name the target. It keeps the ports of
 * every line, and it leads with the first weighty line, so the order of the lines does not change the verdict.
 */
function combine(sightings: readonly Sighting[]): Sighting[] {
  const byKey = new Map<string, Sighting>()
  for (const sighting of sightings) {
    const key = `${recordKey(sighting)}:${sighting.counter}`
    const held = byKey.get(key)
    const lead = held === undefined || (!isWeighty(held) && isWeighty(sighting)) ? sighting : held
    byKey.set(key, { ...lead, ports: distinct([...(held?.ports ?? []), ...sighting.ports], String) })
  }
  return [...byKey.values()]
}

function capPaths(sightings: readonly Sighting[]): Sighting[] {
  const unique = combine(sightings)
  const paths = unique.filter(sighting => sighting.kind === 'path').slice(0, PATH_LIMIT)
  return unique.filter(sighting => sighting.kind !== 'path' || paths.includes(sighting))
}

function hostDetail(host: string, port: number | null): string {
  return port === null ? host : `${host}:${port}`
}

function hostSighting(text: string, counter: 'blocked' | 'listed', reason: BlockReason | null, reasonText: string, program: string): Sighting {
  const { host, port } = splitHost(text)
  return { kind: 'host', target: host, counter, reason, reasonText, ports: port === null ? [] : [port], detail: hostDetail(host, port), program }
}

function pathSighting(path: string, counter: 'blocked' | 'inferred', home: string | undefined, program: string): Sighting {
  const reason: BlockReason = counter === 'blocked' ? 'write' : 'inferred'
  return { kind: 'path', target: folderTarget(path, home), counter, reason, reasonText: '', ports: [], detail: path, program }
}

function reportLines(sources: readonly string[]): string[] {
  const lines = sources.flatMap(source => source.split(OPEN_TAG).slice(1).flatMap(part => part.split(CLOSE_TAG, 1).join('').split('\n')))
  return distinct(lines.map(line => line.trim()).filter(line => line !== ''), line => line)
}

/**
 * The report at the end of the text of a failed call: its last block, when only space or Claude Code's proxy note
 * follows it. The command's output comes before the report, so a block there is output, and the call skips it.
 */
function tailReport(text: string): { lines: string[]; skipped: boolean } {
  const open = text.lastIndexOf(REPORT_OPEN)
  const close = open < 0 ? -1 : text.indexOf(REPORT_CLOSE, open + REPORT_OPEN.length - 1)
  const rest = text.slice(close + REPORT_CLOSE.length)
  const isTail = close >= 0 && (rest.trim() === '' || rest.startsWith(PROXY_NOTE))
  const lines = isTail ? reportLines([text.slice(open, close + REPORT_CLOSE.length)]) : []
  return { lines, skipped: (isTail ? text.slice(0, open) : text).includes(OPEN_TAG) }
}

/**
 * The start of a report line of an unknown form, to name in a diagnostic, or null when the line does not start like a
 * report line: output can imitate a report, so such a line can be any text, even a secret.
 */
export function reportQuote(line: string): string | null {
  return REPORT_START.test(line) ? line.slice(0, UNKNOWN_LIMIT) : null
}

function reportSighting(line: string, home: string | undefined, program: string): Sighting | null {
  const network = NETWORK.exec(line)
  if (network !== null) {
    const [, reported = '', reasonText = ''] = network
    const reason: BlockReason = /user denied/i.test(reasonText) ? 'refused' : reasonText.includes('allowed_domains') ? 'unlisted' : 'other'
    return hostSighting(reported, 'blocked', reason, reasonText, program)
  }
  const [, path] = MAC_WRITE.exec(line) ?? LINUX_WRITE.exec(line) ?? []
  return path === undefined ? null : pathSighting(path, 'blocked', home, program)
}

/** A report line about a file of any operation: the report then speaks for the call's file blocks. */
function isFileLine(line: string): boolean {
  return MAC_FILE.test(line) || LINUX_WRITE.test(line)
}

/** A report line of a form Sandbox Tuner knows: one it counts, or one it knows and ignores (a read, a lookup, a socket). */
function isKnownLine(line: string): boolean {
  return NETWORK.test(line) || MAC_LINE.test(line) || LINUX_WRITE.test(line)
}

/**
 * The path of a permission error: the last path on the line. When a later path does not parse (it holds a space),
 * that one may be the path that was blocked, so the line names none rather than an earlier path in its place.
 */
function inferredPath(line: string, cwd: string | undefined): string | null {
  if (!PERMISSION_ERROR.test(line) || SOCKET_WORDS.test(line)) return null
  const last = Array.from(line.matchAll(PATH_CANDIDATE)).at(-1)
  if (last === undefined && cwd !== undefined) {
    const relative = /(?:^|: )['"]?((?:\.\.?\/)?[a-zA-Z0-9_.-]+(?:\/[a-zA-Z0-9_.-]+)+)['"]?: (?:Operation not permitted|Read-only file system)$/i.exec(line)?.[1]
    return relative === undefined ? null : absolutePath(relative, cwd)
  }
  if (last === undefined || last.index !== Array.from(line.matchAll(PATH_START)).at(-1)?.index) return null
  const [, candidate = ''] = last
  const path = candidate.replace(/\.$/, '')
  return DEVICE_PATH.test(path) ? null : path
}

/** The host and write-folder sightings of one Bash call. */
export function readCall(call: BashCall, outcome: BashOutcome, home: string | undefined, cwd?: string): CallSightings {
  if (outcome.isDenied || (call.isBackground && !outcome.backgroundTaskId)) return { reports: [], gated: [], unknownLine: null }
  const ran = !outcome.isError || EXIT_CODE.test(outcome.text)
  const sources = [outcome.text, outcome.stderr].map(source => source.slice(-SCAN_LIMIT))
  const program = programName(call.command)
  // Claude Code writes the report of a call that succeeded to its error output, apart from the command's output in the
  // text. A failed call has one text: the command's output, then the report, then any proxy note. So only the block at
  // the end of that text counts, and the command can print one there: it is gated below.
  const tail = outcome.isError ? tailReport(outcome.text.slice(-SCAN_LIMIT)) : { lines: reportLines([outcome.stderr.slice(-SCAN_LIMIT)]), skipped: false }
  const { lines } = tail
  const reports = capPaths(lines.flatMap(line => reportSighting(line, home, program) ?? []))
  const listed = ran
    ? combine(call.allowedDomains.filter(entry => !entry.includes('*')).map(entry => hostSighting(entry.trim(), 'listed', null, '', program)))
    : []
  if (outcome.backgroundTaskId !== undefined) {
    return { reports: [], gated: outcome.isError ? [] : listed.filter(fits).map(sighting => ({ gate: 'sandbox-on', sighting })), unknownLine: null }
  }
  const isUnsandboxed = outcome.isUnsandboxed ?? call.isUnsandboxed
  // Without a reported override, strict sandbox mode can have ignored the requested override.
  const canInfer = ran && !outcome.isReadOnly && outcome.isUnsandboxed !== true && !lines.some(isFileLine)
  const inferred = canInfer
    ? capPaths(sources.flatMap(source => source.split('\n')).flatMap(line => {
        const path = inferredPath(line, cwd)
        return path === null ? [] : [pathSighting(path, 'inferred', home, program)]
      }))
    : []
  // The command of a failed call can print a block at the end of its text: it counts only while the sandbox ran the call.
  const reportGate: Gate = isUnsandboxed ? 'sandbox-required' : 'sandbox-on'
  return {
    reports: outcome.isError ? [] : reports.filter(fits),
    gated: [
      ...(outcome.isError ? reports : []).map((sighting): GatedSighting => ({ gate: reportGate, sighting })),
      ...listed.map((sighting): GatedSighting => ({ gate: 'sandbox-on', sighting })),
      ...inferred.map((sighting): GatedSighting => ({ gate: isUnsandboxed ? 'sandbox-required' : 'sandbox-on', sighting })),
    ].filter(({ sighting }) => fits(sighting)),
    observation: lines.flatMap(line => {
      if (reportSighting(line, home, program) !== null) return []
      const operation = /^\S+\(\d+\) deny\(\d+\) (\S+)/.exec(line)?.[1] ?? 'unknown'
      return [{ operation, detail: plainText(line.slice(0, UNKNOWN_LIMIT)) }]
    }).at(-1),
    unknownLine: lines.find(line => !isKnownLine(line)) ?? null,
    skipped: tail.skipped || undefined,
  }
}

export function keepGated(gated: readonly GatedSighting[], facts: SandboxFacts): Sighting[] {
  return gated
    .filter(({ gate }) => facts.isEnabled && (gate === 'sandbox-on' || !facts.allowsUnsandboxed))
    .map(({ sighting }) => sighting)
}

export function latestOf(sightings: readonly Sighting[], command: string, now: number): SandboxTunerLatest | null {
  const block = [...sightings].reverse().find((sighting): sighting is Sighting & { reason: BlockReason } => sighting.reason !== null)
  return block === undefined
    ? null
    : { recordKey: recordKey(block), detail: block.detail, reason: block.reason, reasonText: block.reasonText, command, at: now }
}

files.hooks/verdicts.ts:
// Verdicts: what each record means against the current settings.

import type { Settings } from 'claude-code'

import type { SandboxTunerAction, SandboxTunerRecord, SandboxTunerSettingsKey } from '../types'
import { CLAUDE_PROTECTED, PROTECTED_PLACES, absolutePath, cacheFolder, displayPath, folderTarget, hostMatches, isDnsName, isKeyFile, isProtectedName, isTempFolder, isUnder } from './names'
import { allowCount, sightingTotal } from './records'
import type { FileInfo } from './settings-file'
import { isPlainObject, isText } from './shapes'
import type { SandboxFacts } from './sightings'

export type SourceName = 'user' | 'project' | 'local' | 'flag' | 'policy'
export type Sources = Readonly<Record<SourceName, Settings>>
export type Context = {
  sources: Sources
  home: string | undefined
  configDir: string | undefined
  // Where the protected places and the credentials folders lie: as spelled, or where a press found them.
  protectedDirs: readonly string[]
  credentialDirs: readonly string[]
  pathDirs: readonly string[]
  // Where /tmp lies: as spelled, or where a press found it. Null at the press of a folder outside /tmp, which keeps the
  // rule of Sandbox Tuner 1.1.1.
  tmp: string | null
  cwd: string
  root: string
  threshold: number
  file: FileInfo | undefined
  isCanonical: boolean
}
export type Change = { action: SandboxTunerAction; settingsKey: SandboxTunerSettingsKey; entry: string; file: FileInfo }
export type NoFixReason =
  | 'unverified-path' | 'not-dns' | 'denied-by-settings' | 'managed-lock' | 'protected' | 'credentials' | 'system' | 'too-broad'
  | 'glob' | 'on-path' | 'inside-workspace' | 'deny-rule' | 'write-pattern' | 'read-rule' | 'read-pattern' | 'not-a-cache' | 'no-settings-file'
export type Verdict =
  | { status: 'ready'; allow: Change; deny: Change | null }
  | { status: 'waiting'; deny: Change | null }
  | { status: 'covered'; source: SourceName | 'combined' }
  | { status: 'no-fix'; reason: NoFixReason; detail: string }
export type Rated = { record: SandboxTunerRecord; verdict: Verdict }

type Entry = { text: string; path: string }
type DenialEntry = Entry & { reason: 'read-rule' | 'deny-rule' | 'read-pattern' | 'write-pattern' }

const SOURCE_NAMES: readonly SourceName[] = ['user', 'project', 'local', 'flag', 'policy']
// The sources a repository cannot write: user settings, --settings, and managed settings.
const TRUSTED_SOURCES: readonly SourceName[] = ['user', 'flag', 'policy']
const POLICY_ONLY: readonly SourceName[] = ['policy']
const WEB_FETCH = /^WebFetch\(domain:(.+)\)$/
const GLOB = /[*?[]/
const STATUS_RANK: Readonly<Record<Verdict['status'], number>> = { ready: 0, waiting: 1, 'no-fix': 2, covered: 3 }
// A git or Claude folder outside the working directory, in any letter case: its hooks and settings run outside the sandbox.
const REPO_FOLDERS: ReadonlySet<string> = new Set(['.git', '.claude'])
// Under HOME, beside the protected places that any folder can hold: Claude Code's own settings and the global git configuration.
const HOME_PROTECTED = ['.claude.json', '.config/git']
const CREDENTIAL_FOLDERS = ['.ssh', '.gnupg', '.aws', '.azure', '.config/gcloud', '.config/gh', '.docker', '.netrc', '.npmrc', '.pypirc', '.git-credentials', '.password-store', '.local/share/keyrings', 'Library/Keychains']
const SYSTEM_FOLDERS = ['/bin', '/sbin', '/usr', '/etc', '/private/etc', '/System', '/Library', '/Applications', '/opt/homebrew', '/opt/local', '/nix', '/boot', '/lib', '/lib64']
const READ_BLOCK = 'permissions.blockReadsOutsideWorkingDirectories'
// The roots that hold user files, which the read block closes to sandboxed commands (settings-reference.md).
const USER_ROOTS = ['/Users', '/home', '/root', '/Volumes', '/mnt', '/media', '/run/media', '/srv']

function at(value: unknown, path: readonly string[]): unknown {
  return path.reduce<unknown>((node, name) => (isPlainObject(node) ? node[name] : undefined), value)
}

function strings(value: unknown): string[] {
  return Array.isArray(value) ? value.filter(isText) : []
}

export function sandboxFacts(merged: Settings): SandboxFacts {
  return {
    isEnabled: at(merged, ['sandbox', 'enabled']) === true,
    allowsUnsandboxed: at(merged, ['sandbox', 'allowUnsandboxedCommands']) !== false,
  }
}

function isManagedDomainsOnly(sources: Sources): boolean {
  return at(sources.policy, ['sandbox', 'network', 'allowManagedDomainsOnly']) === true
}

function isStrict(sources: Sources): boolean {
  return TRUSTED_SOURCES.some(name => at(sources[name], ['sandbox', 'network', 'strictAllowlist']) === true)
}

function honoredSources(sources: Sources): readonly SourceName[] {
  const policyRetry = at(sources.policy, ['sandbox', 'allowUnsandboxedCommands'])
  const flagRetry = at(sources.flag, ['sandbox', 'allowUnsandboxedCommands'])
  const isAdminRequired = policyRetry === false || (flagRetry === false && policyRetry !== true) || isManagedDomainsOnly(sources)
  return isAdminRequired ? TRUSTED_SOURCES : SOURCE_NAMES
}

/** The sources whose host entries the sandbox honors. */
function networkAllowSources(sources: Sources): readonly SourceName[] {
  if (isManagedDomainsOnly(sources)) return POLICY_ONLY
  return isStrict(sources) ? TRUSTED_SOURCES : honoredSources(sources)
}

function hostEntries(settings: Settings, list: 'allowedDomains' | 'deniedDomains', rules: 'allow' | 'deny'): string[] {
  const fromRules = strings(at(settings, ['permissions', rules])).flatMap(rule => {
    const [, domain] = WEB_FETCH.exec(rule) ?? []
    return domain === undefined ? [] : [domain]
  })
  return [...strings(at(settings, ['sandbox', 'network', list])), ...fromRules]
}

/** Anchor a settings path without folding `..`: a press follows links before their following segments. */
export function anchorEntry(text: string, source: SourceName, context: Context): string | null {
  const entry = text.replace(/\/\*\*$/, '')
  if (GLOB.test(entry)) return null
  const isHome = entry === '~' || entry.startsWith('~/')
  const base = entry.startsWith('/')
    ? '/'
    : isHome
      ? context.home
      : source === 'user'
        ? context.configDir
        : source === 'project' || source === 'local'
          ? context.root
          : undefined
  return base === undefined ? null : entry.startsWith('/') ? entry : `${base}/${isHome ? entry.slice(2) : entry}`
}

function resolveAll(texts: readonly string[], source: SourceName, context: Context): Entry[] {
  return texts.flatMap(text => {
    const path = anchorEntry(text, source, context)
    return path === null ? [] : [{ text, path: absolutePath(path, '/') }]
  })
}

function entriesOf(context: Context, names: readonly SourceName[], path: readonly string[]): Entry[] {
  return names.flatMap(name => resolveAll(strings(at(context.sources[name], path)), name, context))
}

/** Anchor the last literal parent of a sandbox pattern, retaining links and their following segments. */
function sandboxPath(text: string, source: SourceName, context: Context): { path: string; isPattern: boolean } {
  const entry = text.replace(/\/\*\*$/, '')
  const wildcard = entry.search(GLOB)
  const literal = wildcard < 0 ? entry : entry.slice(0, wildcard)
  const parent = wildcard < 0 ? literal : literal.slice(0, literal.lastIndexOf('/') + 1) || '.'
  return { path: anchorEntry(parent, source, context) ?? '/', isPattern: wildcard >= 0 }
}

/** Denial paths, or the last complete literal parent of each pattern, anchored before following links. */
export function denialEntries(context: Context): DenialEntry[] {
  const entries = permissionEntries(context)
  for (const source of SOURCE_NAMES) {
    for (const list of ['denyWrite', 'denyRead'] as const) {
      for (const text of strings(at(context.sources[source], ['sandbox', 'filesystem', list]))) {
        const { path, isPattern } = sandboxPath(text, source, context)
        const reason = list === 'denyRead' ? (isPattern ? 'read-pattern' : 'read-rule') : (isPattern ? 'write-pattern' : 'deny-rule')
        entries.push({ text, path, reason })
      }
    }
  }
  return entries
}

/** Permission rules use source-relative slash anchors and working-directory relative bare paths. */
function permissionAnchor(pattern: string, source: SourceName, context: Context): { base: string | undefined; entry: string } {
  if (pattern.startsWith('//')) return { base: '/', entry: pattern.slice(2) }
  if (pattern.startsWith('~/')) return { base: context.home, entry: pattern.slice(2) }
  if (pattern.startsWith('/')) return { base: source === 'user' ? context.configDir : source === 'project' || source === 'local' ? context.root : undefined, entry: pattern.slice(1) }
  return { base: context.cwd, entry: pattern.replace(/^\.\//, '') }
}

/** Only a literal subtree can prove coverage of the entire proposed folder. */
function editGrants(context: Context, source: SourceName): Entry[] {
  return strings(at(context.sources[source], ['permissions', 'allow'])).flatMap(text => {
    const pattern = /^Edit\((.+)\/\*\*\)$/.exec(text)?.[1]
    if (pattern === undefined || /[*?[\\!]/.test(pattern)) return []
    const { base, entry } = permissionAnchor(pattern, source, context)
    if (base === undefined) return []
    return [{ text, path: absolutePath(entry, base) }]
  })
}

/** Permission paths have different anchors from sandbox paths. Uncertain patterns cannot justify opening a folder. */
function permissionEntries(context: Context): DenialEntry[] {
  const entries: DenialEntry[] = []
  for (const source of SOURCE_NAMES) {
    for (const rule of strings(at(context.sources[source], ['permissions', 'deny']))) {
      const match = /^(Read|Edit)(?:\((.*)\))?$/.exec(rule)
      if (match === null) continue
      const isRead = match[1] === 'Read'
      const pattern = match[2]
      const uncertainReason = isRead ? 'read-pattern' : 'write-pattern'
      if (pattern === undefined || pattern === '') {
        entries.push({ text: rule, path: '/', reason: uncertainReason })
        continue
      }
      const anchored = permissionAnchor(pattern, source, context)
      const base = anchored.base
      let entry = anchored.entry
      if (!pattern.startsWith('/') && !pattern.startsWith('~/') && !entry.replace(/\/\*\*$/, '').includes('/')) entry = `**/${entry}`
      if (base === undefined) {
        entries.push({ text: rule, path: '/', reason: uncertainReason })
        continue
      }
      entry = entry.replace(/\/\*\*$/, '')
      // Escapes and negation need the full gitignore matcher. Keep their entire anchor uncertain.
      const wildcard = /[\\!]/.test(entry) ? 0 : entry.search(GLOB)
      const literal = wildcard < 0 ? entry : entry.slice(0, wildcard)
      const parent = wildcard < 0 ? literal : literal.slice(0, literal.lastIndexOf('/') + 1)
      entries.push({ text: rule, path: `${base}/${parent}`, reason: wildcard < 0 ? (isRead ? 'read-rule' : 'deny-rule') : uncertainReason })
    }
  }
  return entries
}

/** Denials apply to both a requested path and its real location. */
export function denialVerdict(samples: readonly string[], entries: readonly DenialEntry[]): Verdict | null {
  const denied = entries.find(entry => samples.some(sample => isUnder(absolutePath(sample, '/'), absolutePath(entry.path, '/'))))
  return denied === undefined ? null : noFix(denied.reason, denied.text)
}

/** Keep credential paths anchored for link resolution, using literal parents for patterns and `/` for unknown anchors. */
export function credentialEntries(context: Context): Entry[] {
  return SOURCE_NAMES.flatMap(name => {
    const files = at(context.sources[name], ['sandbox', 'credentials', 'files'])
    const paths = Array.isArray(files) ? files.map(file => at(file, ['path'])) : []
    return strings(paths).map(text => ({ text, path: sandboxPath(text, name, context).path }))
  })
}

/** A folder and each folder above it, up to the root. */
function foldersUp(folder: string): string[] {
  const folders = [folder]
  let at = folder
  while (at !== '/') {
    at = at.slice(0, at.lastIndexOf('/')) || '/'
    folders.push(at)
  }
  return folders
}

/**
 * The protected places and the credentials folders, as spelled: the config dir and its protected names, Claude Code's
 * files and the git configuration under HOME, and the protected places in HOME, in each project folder, and in every
 * folder above a project folder, where Claude Code protects the `.claude` settings too.
 */
export function guardedPlaces(home: string | undefined, configDir: string | undefined, projects: readonly string[]): Pick<Context, 'protectedDirs' | 'credentialDirs'> {
  const under = (folder: string | undefined, names: Iterable<string>) => (folder === undefined ? [] : [...names].map(name => `${folder === '/' ? '' : folder}/${name}`))
  const places = [
    ...(configDir === undefined ? [] : [configDir]),
    ...under(configDir, CLAUDE_PROTECTED),
    ...under(home, HOME_PROTECTED),
    ...[home, ...projects.flatMap(foldersUp)].flatMap(folder => under(folder, PROTECTED_PLACES)),
  ]
  return { protectedDirs: [...new Set(places)], credentialDirs: under(home, CREDENTIAL_FOLDERS) }
}

/**
 * A guarded place that the link check of a folder Allow walks: `levels` is how many levels of folders it lists, the
 * place itself first (Infinity for every level), and `skip` names the folders it never enters, each as a path from the
 * place, where `*` stands for any one name.
 */
export type Walk = { path: string; levels: number; skip: readonly string[] }

// In the config folder, the walk lists only the places where code or settings that run outside the sandbox live.
// It skips the data folders, such as transcripts (projects), todos, logs, and file history. Plugin code is too large to
// list whole, so the walk lists the top two levels of each installed plugin, marketplace, and plugin data folder.
const CONFIG_WALKS: readonly Walk[] = [
  // Beside the protected names: the output styles.
  { path: 'output-styles', levels: Infinity, skip: [] },
  { path: 'plugins', levels: 1, skip: [] },
  // <marketplace>/<plugin>/<version>, then two levels of the plugin.
  { path: 'plugins/cache', levels: 5, skip: [] },
  // <marketplace>, then two levels of it, without its git clone data.
  { path: 'plugins/marketplaces', levels: 3, skip: ['*/.git'] },
  // <plugin>, then two levels of the folder where a plugin keeps its installed dependencies.
  { path: 'plugins/data', levels: 3, skip: [] },
  // A local install of Claude Code.
  { path: 'local', levels: 2, skip: [] },
]

// VS Code keeps the extensions it installs in the `.vscode` folder of HOME. They are too large to list whole, so the
// walk lists the rest of that folder whole, and `extensions`: its top level, then two levels of each extension.
const EDITOR_FOLDER = '.vscode'
const EXTENSIONS_WALK: Walk = { path: 'extensions', levels: 3, skip: [] }

/** Whether a walk skips the folder at `at`, the names from the walked place down to that folder. */
export function isSkipped(skip: readonly string[], at: readonly string[]): boolean {
  return skip.some(entry => {
    const names = entry.split('/')
    return names.length === at.length && names.every((name, index) => name === '*' || name === at[index])
  })
}

/**
 * The walks of the link check over guarded places. Each place is walked whole, except two. The config folder: its top
 * level, its protected names (in `paths` already), and CONFIG_WALKS. The `.vscode` folder of HOME: the rest of it, and
 * EXTENSIONS_WALK. A `.vscode` folder elsewhere holds settings only, so it is walked whole.
 */
export function guardedWalks(paths: readonly string[], { home, configDir }: Pick<Context, 'home' | 'configDir'>): Walk[] {
  const inside = (folder: string, walk: Walk): Walk => ({ ...walk, path: `${folder === '/' ? '' : folder}/${walk.path}` })
  const editor = home === undefined ? undefined : `${home === '/' ? '' : home}/${EDITOR_FOLDER}`
  const walks = paths.map(path => ({ path, levels: path === configDir ? 1 : Infinity, skip: path === editor ? [EXTENSIONS_WALK.path] : [] }))
  const config = configDir !== undefined && paths.includes(configDir) ? CONFIG_WALKS.map(walk => inside(configDir, walk)) : []
  const extensions = editor !== undefined && paths.includes(editor) ? [inside(editor, EXTENSIONS_WALK)] : []
  return [...walks, ...config, ...extensions]
}

/**
 * Each folder that Allow opened that a real place lies inside or holds, and which of the two. As the Allow check does,
 * it compares in any letter case: a file system that ignores case reads two spellings as one place.
 */
export function grantsMet<G extends { place: string }>(place: string, grants: readonly G[]): { grant: G; isInside: boolean }[] {
  const folded = place.toLowerCase()
  return grants.flatMap(grant => {
    const opened = grant.place.toLowerCase()
    const isInside = isUnder(folded, opened)
    return isInside || isUnder(opened, folded) ? [{ grant, isInside }] : []
  })
}

function isProtected(path: string, context: Context): boolean {
  return context.protectedDirs.some(dir => isUnder(path, dir)) || isProtectedName(path)
}

function isCredential(record: SandboxTunerRecord, context: Context): boolean {
  return [record.target, record.sample].some(path => context.credentialDirs.some(dir => isUnder(path, dir))) || isKeyFile(record.sample)
}

function isTooBroad(target: string, home: string | undefined): boolean {
  return target.split('/').filter(part => part !== '').length < 2 || (home !== undefined && isUnder(home, target))
}

function isReadBlocked(path: string, context: Context): boolean {
  const isOn = SOURCE_NAMES.some(name => at(context.sources[name], ['permissions', 'blockReadsOutsideWorkingDirectories']) === true)
  const roots = context.home === undefined ? USER_ROOTS : [context.home, ...USER_ROOTS]
  return isOn && roots.some(root => isUnder(path, root))
}

function noFix(reason: NoFixReason, detail: string): Verdict {
  return { status: 'no-fix', reason, detail }
}

function withFile(context: Context, build: (file: FileInfo) => Verdict): Verdict {
  return context.file === undefined ? noFix('no-settings-file', '') : build(context.file)
}

function byCount(record: SandboxTunerRecord, context: Context, allow: Change, deny: Change | null): Verdict {
  return allowCount(record.counts) < context.threshold ? { status: 'waiting', deny } : { status: 'ready', allow, deny }
}

function hostVerdict(record: SandboxTunerRecord, context: Context): Verdict {
  if (!isDnsName(record.target)) return noFix('not-dns', '')
  const ports = record.ports.length === 0 ? [[]] : record.ports.map(port => [port])
  const denied = SOURCE_NAMES.flatMap(name => hostEntries(context.sources[name], 'deniedDomains', 'deny')).find(entry => ports.some(port => hostMatches(entry, record.target, port)))
  if (denied !== undefined) return noFix('denied-by-settings', denied)
  const allowed = networkAllowSources(context.sources).map(source => ({ source, entries: hostEntries(context.sources[source], 'allowedDomains', 'allow') }))
  const coverage = ports.map(port => allowed.find(({ entries }) => entries.some(entry => hostMatches(entry, record.target, port)))?.source)
  const first = coverage[0]
  if (first !== undefined && coverage.every(source => source !== undefined)) {
    return { status: 'covered', source: coverage.every(source => source === first) ? first : 'combined' }
  }
  if (isManagedDomainsOnly(context.sources)) return noFix('managed-lock', record.target)
  return withFile(context, file => {
    // Deny only a host the person refused at the network prompt. Under strictAllowlist the sandbox refuses it already.
    const canDeny = record.counts.refused > 0 && !isStrict(context.sources)
    const deny: Change | null = canDeny ? { action: 'deny', settingsKey: 'sandbox.network.deniedDomains', entry: record.target, file } : null
    return byCount(record, context, { action: 'allow', settingsKey: 'sandbox.network.allowedDomains', entry: record.target, file }, deny)
  })
}

function pathVerdict(record: SandboxTunerRecord, context: Context): Verdict {
  const { target, sample } = record
  if (isProtected(target, context) || isProtected(sample, context)) return noFix('protected', '')
  if (isCredential(record, context)) return noFix('credentials', '')
  if (SYSTEM_FOLDERS.some(folder => isUnder(target, folder))) return noFix('system', '')
  if (isTooBroad(target, context.home)) return noFix('too-broad', '')
  if (GLOB.test(target)) return noFix('glob', '')
  const pathDir = context.pathDirs.map(dir => absolutePath(dir, '/')).find(dir => isUnder(target, dir) || isUnder(dir, target))
  if (pathDir !== undefined) return noFix('on-path', pathDir)
  if (isUnder(target, context.cwd)) return noFix('inside-workspace', '')
  if (target.toLowerCase().split('/').some(part => REPO_FOLDERS.has(part))) return noFix('protected', '')
  const denied = denialVerdict([sample], denialEntries(context))
  if (denied !== null) return denied
  const credentials = credentialEntries(context).map(entry => ({ ...entry, path: absolutePath(entry.path, '/') }))
  const readRule = credentials.find(entry => isUnder(sample, entry.path))
  if (readRule !== undefined) return noFix('read-rule', readRule.text)
  if (isReadBlocked(sample, context)) return noFix('read-rule', READ_BLOCK)
  const coveredBy = honoredSources(context.sources).find(name =>
    [...entriesOf(context, [name], ['sandbox', 'filesystem', 'allowWrite']), ...entriesOf(context, [name], ['permissions', 'additionalDirectories']), ...editGrants(context, name)]
      .some(entry => isUnder(target, entry.path)),
  )
  if (coveredBy !== undefined) return { status: 'covered', source: coveredBy }
  // A folder strictly inside /tmp that holds the denied file is a temp folder: the target that Sandbox Tuner 1.1.1 names.
  const isTemp = context.tmp !== null && isTempFolder(target, context.home, context.tmp) && folderTarget(sample, context.home) === target
  if (cacheFolder(sample, context.home) !== target && !isTemp) return noFix('not-a-cache', '')
  // A temp folder in a system folder in another letter case, which a file system that ignores case treats as the same.
  if (isTemp && SYSTEM_FOLDERS.some(folder => isUnder(target.toLowerCase(), folder.toLowerCase()))) return noFix('system', '')
  // Guard the entire folder, including credentials elsewhere inside it.
  if (context.protectedDirs.some(dir => isUnder(dir, target))) return noFix('protected', '')
  if ([...context.credentialDirs, ...credentials.map(entry => entry.path)].some(path => isUnder(path, target))) return noFix('credentials', '')
  if (record.counts.inferred > 0) return noFix('unverified-path', '')
  return withFile(context, file => byCount(record, context, { action: 'allow', settingsKey: 'sandbox.filesystem.allowWrite', entry: displayPath(target, context.home), file }, null))
}

export function verdictOf(record: SandboxTunerRecord, context: Context): Verdict {
  switch (record.kind) {
    case 'host':
      return hostVerdict(record, context)
    case 'path':
      return pathVerdict(record, context)
  }
}

function compareRated(a: Rated, b: Rated): number {
  const byTarget = a.record.target < b.record.target ? -1 : a.record.target > b.record.target ? 1 : 0
  return (
    STATUS_RANK[a.verdict.status] - STATUS_RANK[b.verdict.status] ||
    sightingTotal(b.record.counts) - sightingTotal(a.record.counts) ||
    b.record.lastSeen - a.record.lastSeen ||
    byTarget
  )
}

export function rateRecords(records: readonly SandboxTunerRecord[], context: Context): Rated[] {
  return records.map(record => ({ record, verdict: verdictOf(record, context) })).sort(compareRated)
}

